    gilded_grainhopperauger = { name = "Pozlačen spirala za lijake", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen spirala za lijake za mlinarje." },
    jewel_set_grainhopperauger = { name = "Draguljast spirala za lijake", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast spirala za lijake za mlinarje." },
    royal_sovereign_grainhopperauger = { name = "Kraljevski suveren spirala za lijake", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren spirala za lijake z biseri za krono." },
}
