    master_grainhopperauger_atelier = { name = "Mojstrski grainhopperauger atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_grainhopperauger_palace = { name = "Suverena grainhopperauger palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GrainHopperAugerMaker.ironStock=18; GrainHopperAugerMaker.bronzeStock=14; GrainHopperAugerMaker.woodStock=10; GrainHopperAugerMaker.leatherStock=8; GrainHopperAugerMaker.silverStock=8; GrainHopperAugerMaker.goldStock=6; GrainHopperAugerMaker.jewelStock=4; GrainHopperAugerMaker.pearlStock=4
GrainHopperAugerMaker.productStock = {}; GrainHopperAugerMaker.buildings = {}; GrainHopperAugerMaker.maker = nil; GrainHopperAugerMaker.activeMaking = {}; GrainHopperAugerMaker.totalProducts = 0; GrainHopperAugerMaker.dayTimer = 0
function GrainHopperAugerMaker.init() GrainHopperAugerMaker.ironStock=18; GrainHopperAugerMaker.bronzeStock=14; GrainHopperAugerMaker.woodStock=10; GrainHopperAugerMaker.leatherStock=8; GrainHopperAugerMaker.silverStock=8; GrainHopperAugerMaker.goldStock=6; GrainHopperAugerMaker.jewelStock=4; GrainHopperAugerMaker.pearlStock=4; GrainHopperAugerMaker.productStock={}; GrainHopperAugerMaker.buildings={}; GrainHopperAugerMaker.maker=nil; GrainHopperAugerMaker.activeMaking={}; GrainHopperAugerMaker.totalProducts=0; GrainHopperAugerMaker.dayTimer=0; print("[GrainHopperAugerMaker] Royal Grain Hopper Auger Maker System initialized (6 products, 4 buildings)") end
function GrainHopperAugerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainHopperAugerMaker.maker={name=n or ("Spiralar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Spiralar najet: %s (spretnost: %d)",GrainHopperAugerMaker.maker.name,s),"success") end; return true end
function GrainHopperAugerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainHopperAugerMaker.build(id) local ok,e=GrainHopperAugerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainHopperAugerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainHopperAugerMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainHopperAugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainHopperAugerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainHopperAugerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainHopperAugerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainHopperAugerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainHopperAugerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainHopperAugerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainHopperAugerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainHopperAugerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainHopperAugerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainHopperAugerMaker.buildings==0 then return false,"Potrebna spiralna delavnica" end; if not GrainHopperAugerMaker.maker then return false,"Potreben spiralar" end; return true end
function GrainHopperAugerMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainHopperAugerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainHopperAugerMaker.ironStock=GrainHopperAugerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainHopperAugerMaker.bronzeStock=GrainHopperAugerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainHopperAugerMaker.woodStock=GrainHopperAugerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainHopperAugerMaker.leatherStock=GrainHopperAugerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainHopperAugerMaker.silverStock=GrainHopperAugerMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainHopperAugerMaker.goldStock=GrainHopperAugerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainHopperAugerMaker.jewelStock=GrainHopperAugerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainHopperAugerMaker.pearlStock=GrainHopperAugerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainHopperAugerMaker.maker then t=math.max(1,t-math.floor(GrainHopperAugerMaker.maker.skill/13)) end; table.insert(GrainHopperAugerMaker.activeMaking,{id="grainhopperauger_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainHopperAugerMaker.completeMaking(m) local q=1.0+(GrainHopperAugerMaker.getQualityBonus()/100); if GrainHopperAugerMaker.maker then q=q+(GrainHopperAugerMaker.maker.skill/140) end; q=math.min(2.5,q); GrainHopperAugerMaker.productStock[m.productType]=(GrainHopperAugerMaker.productStock[m.productType] or 0)+m.quantity; GrainHopperAugerMaker.totalProducts=GrainHopperAugerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainHopperAugerMaker.maker then GrainHopperAugerMaker.maker.itemsMade=GrainHopperAugerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainHopperAugerMaker.maker.skill=math.min(100,GrainHopperAugerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Spirala izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainhopperauger.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainHopperAugerMaker.update(dt) if not _G.state then return end; GrainHopperAugerMaker.dayTimer=GrainHopperAugerMaker.dayTimer+dt; if GrainHopperAugerMaker.dayTimer>=30 then GrainHopperAugerMaker.dayTimer=0; for i=#GrainHopperAugerMaker.activeMaking,1,-1 do local m=GrainHopperAugerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainHopperAugerMaker.completeMaking(m); table.remove(GrainHopperAugerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainHopperAugerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainHopperAugerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainHopperAugerMaker.getStats() return {ironStock=GrainHopperAugerMaker.ironStock,bronzeStock=GrainHopperAugerMaker.bronzeStock,woodStock=GrainHopperAugerMaker.woodStock,leatherStock=GrainHopperAugerMaker.leatherStock,silverStock=GrainHopperAugerMaker.silverStock,goldStock=GrainHopperAugerMaker.goldStock,jewelStock=GrainHopperAugerMaker.jewelStock,pearlStock=GrainHopperAugerMaker.pearlStock,productStock=GrainHopperAugerMaker.productStock,numBuildings=#GrainHopperAugerMaker.buildings,hasMaker=GrainHopperAugerMaker.maker~=nil,makerName=GrainHopperAugerMaker.maker and GrainHopperAugerMaker.maker.name or "—",makerSkill=GrainHopperAugerMaker.maker and GrainHopperAugerMaker.maker.skill or 0,activeMaking=#GrainHopperAugerMaker.activeMaking,totalProducts=GrainHopperAugerMaker.totalProducts} end
return GrainHopperAugerMaker
